package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func Search(slice []int, value int ) int{

	ultimo := 0

	for index,valueSlice := range slice{
		if(valueSlice == value){
			ultimo = index
		}
	} 

	return ultimo

}

func MagicSearch(slice []int, value int) int {

	left := 0
	rigth :=  len(slice)

	for left < rigth{

		middle := (left + rigth)/2

		if(slice[middle] == value){
			left = Search(slice, value)
			return left
		}else if(slice[middle] < value){
			left = middle + 1
		}else{
			rigth = middle
		}

	}

	return left

}

func main() {
	scanner := bufio.NewScanner(os.Stdin)
	scanner.Scan()
	parts := strings.Fields(scanner.Text())
	slice := make([]int, 0, 1)
	for _, elem := range parts[1 : len(parts)-1] {
		value, _ := strconv.Atoi(elem)
		slice = append(slice, value)
	}

	scanner.Scan()
	value, _ := strconv.Atoi(scanner.Text())
	result := MagicSearch(slice, value)
	fmt.Println(result)
}
